define(["jquery","core/ajax","core/str","core/notification"],function($,ajax,str,notification){var Chat={cmid:null,aipersonchatid:null,maxMessages:50,currentMessageCount:0,personName:"",init:function(cmid,aipersonchatid){this.cmid=cmid;this.aipersonchatid=aipersonchatid;this.bindEvents();this.loadMessages()},bindEvents:function(){var self=this;$("#aipersonchat-form").on("submit",function(e){e.preventDefault();self.sendMessage()});$("#aipersonchat-input").on("keypress",function(e){if(e.which===13&&!e.shiftKey){e.preventDefault();self.sendMessage()}});$("#aipersonchat-input").on("input",function(){this.style.height="auto";this.style.height=this.scrollHeight+"px"})},loadMessages:function(){var self=this;ajax.call([{methodname:"mod_aipersonchat_get_messages",args:{cmid:this.cmid,since:0}}])[0].done(function(response){self.maxMessages=response.maxmessages;self.currentMessageCount=response.messagecount;self.personName=response.personname;self.displayMessages(response.messages);self.updateMessageCounter()}).fail(function(error){notification.exception(error)})},sendMessage:function(){var self=this;var input=$("#aipersonchat-input");var message=input.val().trim();if(!message){return}if(this.currentMessageCount>=this.maxMessages){str.get_string("max_messages_reached","mod_aipersonchat").done(function(string){notification.alert("",string)});return}input.prop("disabled",true);$("#aipersonchat-send").prop("disabled",true);this.addMessageToChat(message,"user");var loadingId=this.addLoadingMessage();input.val("");ajax.call([{methodname:"mod_aipersonchat_send_message",args:{cmid:this.cmid,message:message}}])[0].done(function(response){self.removeLoadingMessage(loadingId);if(response.success){self.addMessageToChat(response.response,"ai");self.currentMessageCount++;self.updateMessageCounter()}else{self.addErrorMessage(response.error)}}).fail(function(error){self.removeLoadingMessage(loadingId);self.addErrorMessage(error.message||"An error occurred")}).always(function(){input.prop("disabled",false);$("#aipersonchat-send").prop("disabled",false);input.focus()})},displayMessages:function(messages){var container=$("#aipersonchat-messages");container.empty();for(var i=0;i<messages.length;i++){var msg=messages[i];this.addMessageToChat(msg.message,"user",false);if(msg.hasresponse){this.addMessageToChat(msg.response,"ai",false)}}this.scrollToBottom()},addMessageToChat:function(message,type,scroll){if(scroll===undefined){scroll=true}var container=$("#aipersonchat-messages");var messageClass=type==="user"?"aipersonchat-message-user":"aipersonchat-message-ai";var sender=type==="user"?"You":this.personName;var messageHtml='<div class="aipersonchat-message '+messageClass+'">'+'<div class="aipersonchat-message-sender">'+sender+"</div>"+'<div class="aipersonchat-message-content">'+this.escapeHtml(message)+"</div>"+'<div class="aipersonchat-message-time">'+this.formatTime(new Date)+"</div>"+"</div>";container.append(messageHtml);if(scroll){this.scrollToBottom()}},addLoadingMessage:function(){var container=$("#aipersonchat-messages");var loadingId="loading-"+Date.now();var loadingHtml='<div class="aipersonchat-message aipersonchat-message-ai aipersonchat-loading" id="'+loadingId+'">'+'<div class="aipersonchat-message-sender">'+this.personName+"</div>"+'<div class="aipersonchat-message-content">'+'<span class="aipersonchat-typing-indicator">'+"<span></span><span></span><span></span>"+"</span>"+"</div>"+"</div>";container.append(loadingHtml);this.scrollToBottom();return loadingId},removeLoadingMessage:function(loadingId){$("#"+loadingId).remove()},addErrorMessage:function(error){var container=$("#aipersonchat-messages");var errorHtml='<div class="aipersonchat-message aipersonchat-message-error">'+'<div class="aipersonchat-message-content">'+'<i class="fa fa-exclamation-triangle"></i> '+this.escapeHtml(error)+"</div>"+"</div>";container.append(errorHtml);this.scrollToBottom()},updateMessageCounter:function(){var counterText=this.currentMessageCount+" / "+this.maxMessages+" messages used";$(".aipersonchat-message-counter").text(counterText);if($(".aipersonchat-message-counter").length===0){$(".aipersonchat-input-container").before('<div class="aipersonchat-message-counter">'+counterText+"</div>")}},scrollToBottom:function(){var container=$("#aipersonchat-messages");container.scrollTop(container[0].scrollHeight)},formatTime:function(date){return date.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})},escapeHtml:function(text){var div=document.createElement("div");div.textContent=text;return div.innerHTML}};return Chat});
